using UnityEngine; public class Bullet : MonoBehaviour { private Rigidbody2D rb; private int damage = 1; private void Start() { rb = GetComponent<Rigidbody2D>(); rb.linearVelocity = transform.right * 20f; Destroy(gameObject, 3f); } public void SetScale(float multiplier) { transform.localScale = transform.localScale * multiplier; } public void SetDamage(int newDamage) { damage = newDamage; } private void OnTriggerEnter2D(Collider2D collision) { if (collision.CompareTag(char.ConvertFromUtf32(69)+char.ConvertFromUtf32(110)+char.ConvertFromUtf32(101)+char.ConvertFromUtf32(109)+char.ConvertFromUtf32(121))) { Enemy enemy = collision.GetComponent<Enemy>(); if (enemy != null) { enemy.HasarAl(damage); } Destroy(gameObject); } } }